(()=>{'use strict';const $=id=>document.getElementById(id);if(!$('pixForm'))return;
const paymentAccess=mac=>{const k=mac.startsWith('roku_')?'elvanoq_pix_roku_'+mac.slice(5).toUpperCase():'elvanoq_pix_'+(mac.startsWith('webos_')?'webos_':'')+mac.replace(/[^0-9a-f]/gi,'').toUpperCase();let access=sessionStorage.getItem(k);if(!access){access=Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b=>b.toString(16).padStart(2,'0')).join('');sessionStorage.setItem(k,access);}return access;};
const {url,publishableKey}=window.ELVANOQ_CONFIG;let order=null,identity=null,timer=null,checks=0,paymentsEnabled=false;
const say=(text,success=false)=>{const el=$('pixMessage');el.hidden=!text;el.textContent=text;el.classList.toggle('success',success);};
async function api(body){const tv=body.platform==='webos'||body.platform==='samsung'||body.platform==='ios'||body.platform==='titan'||body.platform==='vidaa';const payload=tv?{...body,platform:'webos',action:'webos-checkout',operation:body.action}:body;const r=await fetch(url+'/functions/v1/'+(tv?'portal-control':'paghiper-payments'),{method:'POST',headers:{apikey:publishableKey,'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(30000),cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.message||'Não foi possível consultar o pagamento.');return d;}
const labels={creating:'Emissão em conferência',unknown:'Emissão em conferência',pending:'Aguardando pagamento',processing:'Pagamento em análise',paid:'Pagamento aprovado',completed:'Pagamento aprovado',expired:'Pix vencido. Gere uma nova cobrança para pagar.',canceled:'Cobrança cancelada',refunded:'Pagamento estornado — contate o responsável'};
function render(o){order=o;$('pixResult').hidden=false;$('pixOrderSummary').textContent=(o.deviceCode?'TV Roku '+o.deviceCode:o.tv_code?'TV '+o.tv_code:'MAC '+o.mac)+' · R$ '+(o.amount_cents/100).toFixed(2).replace('.',',')+' · Pedido '+o.id+(o.due_date?' · Vencimento '+o.due_date:'');$('pixCode').value=o.emv||'';const png=o.qrcode_base64;if(typeof png==='string'&&png.startsWith('iVBORw0KGgo')&&png.length<100000){$('pixQr').src='data:image/png;base64,'+png;$('pixQr').hidden=false;}else{$('pixQr').hidden=true;}$('copyPix').hidden=!o.emv;$('pixStatus').textContent=labels[o.status]||'Aguardando conferência';if(o.applied_at&&['paid','completed'].includes(o.status)){$('pixStatus').textContent='Pagamento confirmado. Licença anual liberada até '+new Date(o.license_until).toLocaleDateString('pt-BR')+'.';clearInterval(timer);$('generatePix').disabled=true;say('Licença atualizada. Abra ou retorne ao aplicativo para ele verificar a ativação automaticamente.',true);}else if(['canceled','refunded','expired'].includes(o.status)){clearInterval(timer);}}
async function check(){if(!order||!identity)return;const b=$('checkPix');b.disabled=true;try{const d=await api({action:'status',order_id:order.id,...identity});render(d.order);}catch(e){say(e.name==='TimeoutError'?'Consulta demorou. Tente consultar novamente.':e.message);}finally{b.disabled=false;}}
$('pixForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('generatePix');button.disabled=true;$('devicePlatform').disabled=true;say('Gerando cobrança. Aguarde antes de tentar novamente.');const platform=$('devicePlatform').value,roku=platform==='roku',tv=platform==='webos'||platform==='samsung'||platform==='ios'||platform==='titan'||platform==='vidaa',pattern=platform==='vidaa'?/^VD-[0-9A-F]{12}$/:platform==='titan'?/^TT-[0-9A-F]{12}$/:platform==='ios'?/^IOS-[0-9A-F]{12}$/:platform==='samsung'?/^SM-[0-9A-F]{12}$/:/^LG-[0-9A-F]{12}$/,native=tv||roku;const identifier=native?$('tvCode').value.replace(/\s/g,'').toUpperCase():$('pixMac').value.trim();identity=roku?{platform:'roku',deviceCode:identifier,device_key:$('pixKey').value.trim(),payment_access:paymentAccess('roku_'+identifier)}:tv?{platform:platform,tv_code:identifier,device_key:$('pixKey').value.trim(),payment_access:paymentAccess('webos_'+identifier)}:{mac:identifier,payment_access:paymentAccess(identifier)};try{if(roku){if(identifier.length!==22||!/^ROKU-[A-Z0-9]{8}-[A-Z0-9]{8}$/.test(identifier)||!/^[-A-Za-z0-9]{6,128}$/.test(identity.device_key))throw new Error('Confira o código Roku e a chave exibidos na TV.');await api({action:'validate',...identity});}if(tv){if(!pattern.test(identifier)||!/^\d{6,128}$/.test(identity.device_key))throw new Error('Confira o código da TV e a chave numérica exibidos na tela.');await api({action:'validate',...identity});}const d=await api({action:'create',...identity,payer_name:$('payerName').value.trim(),payer_email:$('payerEmail').value.trim(),payer_cpf_cnpj:$('payerDocument').value,consent:$('pixConsent').checked});render(d.order);say('Use o QR Code ou o Pix Copia e Cola. A confirmação é consultada automaticamente.');$('payerDocument').value='';clearInterval(timer);checks=0;if(!d.order.applied_at)timer=setInterval(()=>{if(++checks>120){clearInterval(timer);return;}if(!document.hidden)check();},15000);}catch(e){say(e.name==='TimeoutError'?'A emissão demorou. Consulte o responsável antes de gerar outra cobrança.':e.message);}finally{$('devicePlatform').disabled=false;if(!order?.applied_at)button.disabled=false;}});
$('devicePlatform').addEventListener('change',()=>{const platform=$('devicePlatform').value,roku=platform==='roku',samsung=platform==='samsung',vidaa=platform==='vidaa',titan=platform==='titan',ios=platform==='ios',tv=platform==='webos'||samsung||ios||titan||vidaa,native=tv||roku;clearInterval(timer);order=null;identity=null;$('pixResult').hidden=true;say('');$('androidIdentity').hidden=native;$('lgIdentity').hidden=!native;$('webosInstructions').hidden=!native;$('androidPaymentNote').hidden=native;$('pixMac').required=!native;$('tvCode').required=native;$('pixKey').required=native;$('pixKey').value='';$('tvCode').value='';$('tvCodeLabel').textContent=roku?'Código da TV Roku':vidaa?'Código da TV VIDAA':titan?'Código da TV Titan OS':ios?'Código iPhone / iPad':samsung?'Código da TV Samsung':'Código da TV LG';$('tvCode').maxLength=128;$('tvCode').pattern=roku?'ROKU-[A-Z0-9]{8}-[A-Z0-9]{8}':vidaa?'VD-[0-9A-F]{12}':titan?'TT-[0-9A-F]{12}':ios?'IOS-[0-9A-F]{12}':samsung?'SM-[0-9A-F]{12}':'LG-[0-9A-F]{12}';$('tvCode').placeholder=roku?'ROKU-XXXXXXXX-XXXXXXXX':vidaa?'VD-XXXXXXXXXXXX':titan?'TT-XXXXXXXXXXXX':ios?'IOS-XXXXXXXXXXXX':samsung?'SM-XXXXXXXXXXXX':'LG-XXXXXXXXXXXX';$('webosInstructions').textContent=roku?'Abra primeiro o ELVANOQ Play na sua Roku e informe o código e a chave exibidos na TV.':vidaa?'Abra o ELVANOQ Play na TV VIDAA (Hisense/Toshiba) e informe o código VD- exibido na tela.':titan?'Abra o ELVANOQ Play na TV Titan OS e informe o código TT- e a chave exibidos na tela.':ios?'Abra o ELVANOQ Play no iPhone ou iPad pelo Media Station X e informe o código e a chave exibidos.':samsung?'Abra o ELVANOQ Play na TV Samsung, pelo app nativo ou Media Station X, e informe o código SM- e a chave exibidos.':'Abra o ELVANOQ Play na TV LG, pelo app nativo ou Media Station X, e informe o código LG- e a chave exibidos.';$('pixKey').pattern=roku?'[A-Za-z0-9-]{6,128}':tv?'[0-9]{6,128}':'.*';$('pixKeyLabel').textContent=native?'Chave do dispositivo':'Chave do dispositivo (opcional)';$('generatePix').disabled=!paymentsEnabled;});
$('tvCode').addEventListener('input',()=>{const platform=$('devicePlatform').value,roku=platform==='roku',samsung=platform==='samsung',vidaa=platform==='vidaa',titan=platform==='titan',ios=platform==='ios';const value=$('tvCode').value.toUpperCase(),prefix=roku?'ROKU-':vidaa?'VD-':titan?'TT-':ios?'IOS-':samsung?'SM-':'LG-',strip=roku?/^ROKU[\s-]*/:vidaa?/^VD[\s-]*/:titan?/^TT[\s-]*/:ios?/^IOS[\s-]*/:samsung?/^SM[\s-]*/:/^LG[\s-]*/,body=value.replace(strip,'').replace(roku?/[^A-Z0-9]/g:/[^A-F0-9]/g,'').slice(0,roku?16:12);$('tvCode').value=prefix+(roku?body.slice(0,8)+(body.length>8?'-'+body.slice(8):''):body);});
$('checkPix').addEventListener('click',check);$('copyPix').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('pixCode').value);say('Código Pix copiado.',true);}catch{$('pixCode').focus();$('pixCode').select();say('Selecione e copie o código Pix.');}});
api({action:'config'}).then(d=>{$('paymentAvailability').textContent=d.enabled?'Pix PagHiper disponível. Liberação após confirmação do pagamento.':'Pix PagHiper em configuração. A emissão de cobranças ainda não está disponível.';paymentsEnabled=!!d.enabled;$('generatePix').disabled=!d.enabled;}).catch(()=>{$('paymentAvailability').textContent='Não foi possível consultar a disponibilidade do Pix. Tente novamente mais tarde.';});
window.addEventListener('pagehide',()=>clearInterval(timer));})();
